import fse from 'fs-extra';
import { mkdtemp, rm } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';
import { fileURLToPath } from 'url';
const notFound = (code, message = "Cannot find package '@mintlify/package-builder' imported from /cli/dist/index.js") => Object.assign(new Error(message), { code });
vi.mock('../packages/builder.js', async (importOriginal) => {
    const actual = await importOriginal();
    return {
        ...actual,
        loadPackageBuilder: () => actual.loadPackageBuilder(() => Promise.reject(notFound('ERR_MODULE_NOT_FOUND'))),
    };
});
import { PackagesDev } from '../local-preview/packages/dev.js';
import { PACKAGE_BUILDER_MISSING } from '../packages/builder.js';
const actualLoad = async () => (await vi.importActual('../packages/builder.js'))
    .loadPackageBuilder;
const PAGE = `import { LineChart } from "recharts";

<LineChart width={400} height={200} data={[{ v: 1 }]} />
`;
describe('loadPackageBuilder', () => {
    it.each(['ERR_MODULE_NOT_FOUND', 'MODULE_NOT_FOUND'])('explains how to get npm packages back on %s', async (code) => {
        const load = await actualLoad();
        await expect(load(() => Promise.reject(notFound(code)))).rejects.toThrow(PACKAGE_BUILDER_MISSING);
    });
    it('passes other errors through', async () => {
        const error = Object.assign(new Error('EACCES: permission denied'), { code: 'EACCES' });
        const load = await actualLoad();
        await expect(load(() => Promise.reject(error))).rejects.toBe(error);
    });
    it('passes through a missing dependency of an installed builder', async () => {
        const error = notFound('ERR_MODULE_NOT_FOUND', "Cannot find package 'entities' imported from /cli/node_modules/@mintlify/package-builder/dist/sanitize.js");
        const load = await actualLoad();
        await expect(load(() => Promise.reject(error))).rejects.toBe(error);
    });
    it('loads the builder when it is installed', async () => {
        const load = await actualLoad();
        expect(typeof (await load()).build).toBe('function');
    });
    it('pins the builder version from this workspace so releases publish them together', async () => {
        const packageJson = (path) => fse.readJson(fileURLToPath(new URL(`../../../${path}/package.json`, import.meta.url)));
        const previewing = await packageJson('previewing');
        const builder = await packageJson('package-builder');
        expect(previewing.optionalDependencies['@mintlify/package-builder']).toBe(builder.version);
    });
});
describe('without @mintlify/package-builder installed', () => {
    let root;
    let docsRoot;
    beforeEach(async () => {
        root = await mkdtemp(join(tmpdir(), 'packages-builder-'));
        docsRoot = join(root, 'docs');
        await fse.outputJson(join(docsRoot, 'docs.json'), { name: 'Docs', packages: {} });
        await fse.outputJson(join(docsRoot, 'package.json'), { dependencies: { recharts: '2.15.4' } });
        await fse.outputFile(join(docsRoot, 'charts.mdx'), PAGE);
    });
    afterEach(async () => {
        await rm(root, { recursive: true, force: true });
    });
    it('reports the reinstall hint in mint dev and shows it on package components', async () => {
        const failed = vi.fn();
        const dev = new PackagesDev({
            docsRoot,
            buildsDir: join(root, 'builds'),
            propsPath: join(root, 'props'),
            onRebuilt: () => { },
            reporter: {
                building: () => { },
                built: () => { },
                failed,
                missingNodeModules: () => { },
                islandErrors: () => { },
                configError: () => { },
            },
            debounceMs: 0,
            pollMs: 10,
        });
        try {
            await dev.init();
            expect(failed).toHaveBeenCalledWith([PACKAGE_BUILDER_MISSING], []);
            expect(dev.getStatus()).toEqual({ state: 'failed', message: PACKAGE_BUILDER_MISSING });
        }
        finally {
            await dev.close();
        }
    });
});
